-- A workflow chooses its coordination owner once. Existing workflows stay legacy.
CREATE TABLE workflow_conversations (workflow_id TEXT PRIMARY KEY REFERENCES workflows(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), agent_id TEXT NOT NULL REFERENCES roles(id), mode TEXT NOT NULL CHECK(mode='chat'), version INTEGER NOT NULL DEFAULT 0, automatic_turns INTEGER NOT NULL DEFAULT 0, blocked_reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE turn_triggers (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), agent_id TEXT NOT NULL REFERENCES roles(id), kind TEXT NOT NULL CHECK(kind IN ('task_event','manual_wake')), dedupe_key TEXT NOT NULL UNIQUE, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','claimed','consumed','failed','interrupted')), turn_id TEXT, error TEXT, created_at TEXT NOT NULL, ended_at TEXT);
CREATE TABLE coordination_cursors (consumer TEXT PRIMARY KEY, event_seq INTEGER NOT NULL);
INSERT INTO coordination_cursors VALUES('chat',0);
CREATE TABLE coordination_outbox (id TEXT PRIMARY KEY, event_seq INTEGER NOT NULL REFERENCES task_events(event_seq), workflow_id TEXT NOT NULL REFERENCES workflows(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), kind TEXT NOT NULL CHECK(kind IN ('receipt','wake')), payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempt INTEGER NOT NULL DEFAULT 0, error TEXT, next_retry_at TEXT, created_at TEXT NOT NULL, UNIQUE(event_seq,conversation_id,kind));
-- Kept separate from model-authored messages: system facts never impersonate an agent.
CREATE TABLE coordination_receipts (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), workflow_id TEXT NOT NULL REFERENCES workflows(id), event_seq INTEGER NOT NULL REFERENCES task_events(event_seq), payload TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(event_seq,conversation_id));
CREATE TRIGGER coordination_receipt_event AFTER INSERT ON coordination_receipts BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,payload,occurred_at) VALUES(NEW.workspace_id,'coordination.receipt',NEW.id,NEW.payload,NEW.created_at); END;
DROP TRIGGER turn_scope;
DROP TRIGGER turn_insert_event;
DROP TRIGGER turn_update_event;
DROP INDEX turn_queue;
ALTER TABLE agent_turns RENAME TO agent_turns_legacy;
CREATE TABLE agent_turns (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), message_id TEXT UNIQUE REFERENCES messages(id), agent_id TEXT NOT NULL REFERENCES roles(id), status TEXT NOT NULL CHECK(status IN ('queued','running','stopping','completed','failed','cancelled','interrupted')), configuration TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, cleanup_status TEXT NOT NULL DEFAULT 'pending', error TEXT, created_at TEXT NOT NULL, started_at TEXT, ended_at TEXT, runtime_boot_id TEXT, trigger_id TEXT UNIQUE REFERENCES turn_triggers(id), CHECK(message_id IS NOT NULL OR trigger_id IS NOT NULL));
INSERT INTO agent_turns SELECT *,NULL FROM agent_turns_legacy;
DROP TABLE agent_turns_legacy;
CREATE INDEX turn_queue ON agent_turns(status,created_at);
CREATE TRIGGER turn_scope BEFORE INSERT ON agent_turns WHEN (SELECT workspace_id FROM conversations WHERE id=NEW.conversation_id)<>NEW.workspace_id OR (SELECT workspace_id FROM roles WHERE id=NEW.agent_id)<>NEW.workspace_id OR (NEW.message_id IS NOT NULL AND ((SELECT workspace_id FROM messages WHERE id=NEW.message_id)<>NEW.workspace_id OR (SELECT conversation_id FROM messages WHERE id=NEW.message_id)<>NEW.conversation_id OR (SELECT recipient_agent_id FROM messages WHERE id=NEW.message_id)<>NEW.agent_id)) OR (NEW.trigger_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM turn_triggers t WHERE t.id=NEW.trigger_id AND t.workspace_id=NEW.workspace_id AND t.conversation_id=NEW.conversation_id AND t.agent_id=NEW.agent_id)) BEGIN SELECT RAISE(ABORT,'cross-workspace turn'); END;
CREATE TRIGGER turn_insert_event AFTER INSERT ON agent_turns BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.workspace_id,'turn.queued',NEW.id,NEW.version,NEW.created_at); END;
CREATE TRIGGER turn_update_event AFTER UPDATE ON agent_turns BEGIN INSERT INTO workspace_events(workspace_id,type,entity_id,entity_version,occurred_at) VALUES(NEW.workspace_id,'turn.updated',NEW.id,NEW.version,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TABLE coordination_decisions (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id), turn_id TEXT NOT NULL UNIQUE REFERENCES agent_turns(id), owner_version INTEGER NOT NULL, plan_revision INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','handoff_requested','completed','failed','interrupted')), tool_calls INTEGER NOT NULL DEFAULT 0, stagnant_calls INTEGER NOT NULL DEFAULT 0, last_event_seq INTEGER NOT NULL DEFAULT 0, handoff TEXT, error TEXT, created_at TEXT NOT NULL, ended_at TEXT);
CREATE UNIQUE INDEX one_workflow_decision ON coordination_decisions(workflow_id) WHERE status IN ('active','handoff_requested','interrupted');
INSERT INTO schema_migrations(version,applied_at) VALUES(12,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
